-- Umber — an earth palette.
-- Generated by umber/neovim.py — do not edit by hand.
-- Syntax accents come from umber/editor.py: chroma is level across
-- keywords, functions, types, strings and literals, so hue separates
-- them and no role is muted relative to another.
-- Both variants, picked by 'background', which Neovim sets from the
-- terminal (OSC 11, and DEC 2031 when Ghostty follows the appearance).
-- Never set 'background' here: Neovim then stops updating it at VimEnter,
-- and drops the scheme on the next change.

vim.cmd("highlight clear")
if vim.fn.exists("syntax_on") == 1 then vim.cmd("syntax reset") end
vim.g.colors_name = "umber"

